LinkQueue* InitQueue()
//创建一个带头结点的空队
{
    LinkQueue *q;
    QueueNode *p;
    q=(LinkQueue*)malloc(sizeof(LinkQueue)); //申请头尾指针结点
    p=(QueueNode*)malloc(sizeof(QueueNode)); //申请链队列头结点
    p->next=NULL;
    q->front=q->rear=p;
    return q;
}

int QueueEmpty(LinkQueue *q)
//链队列为空时返回值为真，反之为假
{ return(q->front==q->rear?TRUE:FALSE); }

void EnQueue(LinkQueue *q, Elemtype e)
{
    // 将元素 e 进队，即在表尾插入新的结点
    QueueNode *s;
    s = (QueueNode*)malloc(sizeof(QueueNode));
    s->data = e;
    s->next = NULL;
    q->rear->next = s;
    q->rear = s;
}

int DeQueue(LinkQueue *q, Elemtype &e)
{
    //若队列不为空将出队，即为删除队头结点
    QueueNode *p;
    if(QueueEmpty(q)) return ERROR;    //队空
    p=q->front->next;
    e=p->data;
    q->front->next=p->next;
    free(p);
    if(q->front->next==NULL) q->rear=q->front;
    return OK;
}

int QueueLength(LinkQueue *q)
{
    QueueNode *p; int len=0;
    p=q->front->next;
    while(p)
    { len++;
    p=p->next;
    }
    return len;
}
